package main

import (
  "bytes"
  "encoding/json"
  "fmt"
  "io"
  "net"
  "net/http"
  "os"
  "os/exec"
  "path/filepath"
  "runtime"
  "strings"
  "sync"
  "time"
)

type Settings struct { OpenRouterKey string `json:"openRouterKey"`; DropboxPath string `json:"dropboxPath"`; Model string `json:"model"` }
type Document struct { ID, ProjectID, Name, Path, CreatedAt, Status string; Size int64 }
type State struct { Settings Settings `json:"settings"`; Documents []Document `json:"documents"` }
type App struct { mu sync.Mutex; root, dataFile string; state State; ln net.Listener }

func dataDir() string { if p:=os.Getenv("LOCALAPPDATA"); p!="" { return filepath.Join(p,"DirecaoFiscalizacaoObra") }; h,_:=os.UserHomeDir(); return filepath.Join(h,"DirecaoFiscalizacaoObra") }
func newApp()*App{ r:=dataDir(); os.MkdirAll(r,0755); a:=&App{root:r,dataFile:filepath.Join(r,"app.json"),state:State{Settings:Settings{Model:"openai/gpt-5-mini"},Documents:[]Document{}}}; if b,e:=os.ReadFile(a.dataFile);e==nil{_ = json.Unmarshal(b,&a.state)}; a.save(); return a }
func(a *App) save(){ b,_:=json.MarshalIndent(a.state,"","  "); _=os.WriteFile(a.dataFile,b,0644) }
func send(w http.ResponseWriter,status int,v any){ w.Header().Set("Content-Type","application/json; charset=utf-8"); w.Header().Set("Cache-Control","no-store"); w.WriteHeader(status); _=json.NewEncoder(w).Encode(v) }
func writable(p string)(bool,string){ st,e:=os.Stat(p); if e!=nil{return false,e.Error()}; if !st.IsDir(){return false,"O caminho não é uma pasta."}; t:=filepath.Join(p,fmt.Sprintf(".dfobra_%d.tmp",time.Now().UnixNano())); if e=os.WriteFile(t,[]byte("ok"),0644);e!=nil{return false,e.Error()}; _=os.Remove(t); return true,"" }
func detectDropbox()string{ h,_:=os.UserHomeDir(); for _,p:=range []string{filepath.Join(h,"Dropbox"),filepath.Join(h,"Dropbox (Personal)")} { if st,e:=os.Stat(p);e==nil&&st.IsDir(){return p} }; if la:=os.Getenv("LOCALAPPDATA");la!=""{ b,e:=os.ReadFile(filepath.Join(la,"Dropbox","info.json")); if e==nil{ var x map[string]map[string]any; if json.Unmarshal(b,&x)==nil{ for _,v:=range x{ if p,ok:=v["path"].(string);ok{ if st,e:=os.Stat(p);e==nil&&st.IsDir(){return p} } } } } }; return "" }
func request(method,url,key string,payload any)(map[string]any,error){ var body io.Reader; if payload!=nil{b,_:=json.Marshal(payload);body=bytes.NewReader(b)}; req,e:=http.NewRequest(method,url,body);if e!=nil{return nil,e};if key!=""{req.Header.Set("Authorization","Bearer "+key)};if payload!=nil{req.Header.Set("Content-Type","application/json")}; c:=&http.Client{Timeout:40*time.Second}; r,e:=c.Do(req);if e!=nil{return nil,e};defer r.Body.Close(); b,_:=io.ReadAll(io.LimitReader(r.Body,4<<20)); var out map[string]any; _=json.Unmarshal(b,&out); if r.StatusCode<200||r.StatusCode>=300{return nil,fmt.Errorf("HTTP %d: %s",r.StatusCode,string(b))}; return out,nil }
func(a *App) api(w http.ResponseWriter,r *http.Request){ p:=r.URL.Path
 if p=="/api/health"{send(w,200,map[string]any{"ok":true,"version":"4.0.0"});return}
 if p=="/api/state"{a.mu.Lock();defer a.mu.Unlock();send(w,200,map[string]any{"settings":map[string]any{"openRouterKey":func()string{if a.state.Settings.OpenRouterKey!=""{return "***"};return ""}(),"dropboxPath":a.state.Settings.DropboxPath},"documents":a.state.Documents,"connections":map[string]bool{"openrouter":a.state.Settings.OpenRouterKey!="","dropbox":a.state.Settings.DropboxPath!=""}});return}
 if p=="/api/settings/openrouter"&&r.Method=="POST"{var b struct{Key string `json:"key"`};if json.NewDecoder(r.Body).Decode(&b)!=nil||len(strings.TrimSpace(b.Key))<10{send(w,400,map[string]any{"error":"Chave inválida."});return};a.mu.Lock();a.state.Settings.OpenRouterKey=strings.TrimSpace(b.Key);a.save();a.mu.Unlock();send(w,200,map[string]any{"ok":true});return}
 if p=="/api/openrouter/test"&&r.Method=="POST"{a.mu.Lock();k:=a.state.Settings.OpenRouterKey;a.mu.Unlock();if k==""{send(w,400,map[string]any{"error":"Chave OpenRouter não configurada."});return};_,e:=request("GET","https://openrouter.ai/api/v1/models",k,nil);if e!=nil{send(w,502,map[string]any{"error":e.Error()});return};send(w,200,map[string]any{"ok":true});return}
 if p=="/api/ask"&&r.Method=="POST"{var b struct{Prompt string `json:"prompt"`};_ = json.NewDecoder(r.Body).Decode(&b);a.mu.Lock();k:=a.state.Settings.OpenRouterKey;m:=a.state.Settings.Model;a.mu.Unlock();if k==""{send(w,400,map[string]any{"error":"Chave OpenRouter não configurada."});return};out,e:=request("POST","https://openrouter.ai/api/v1/chat/completions",k,map[string]any{"model":m,"messages":[]map[string]string{{"role":"system","content":"És o assistente da plataforma Direção e Fiscalização de Obra. Responde em português de Portugal. Sê proativo, objetivo e orientado para prazo, custo, qualidade, segurança, documentação e antecipação de risco."},{"role":"user","content":b.Prompt}},"temperature":0.2});if e!=nil{send(w,502,map[string]any{"error":e.Error()});return};text:="Sem resposta.";if c,ok:=out["choices"].([]any);ok&&len(c)>0{if x,ok:=c[0].(map[string]any);ok{if mm,ok:=x["message"].(map[string]any);ok{if t,ok:=mm["content"].(string);ok{text=t}}}};send(w,200,map[string]any{"ok":true,"text":text});return}
 if p=="/api/dropbox/detect"&&r.Method=="POST"{d:=detectDropbox();if d==""{send(w,404,map[string]any{"error":"Dropbox não encontrada automaticamente."});return};a.mu.Lock();a.state.Settings.DropboxPath=d;a.save();a.mu.Unlock();send(w,200,map[string]any{"ok":true,"path":d});return}
 if p=="/api/dropbox/set"&&r.Method=="POST"{var b struct{Path string `json:"path"`};_=json.NewDecoder(r.Body).Decode(&b);ok,msg:=writable(strings.TrimSpace(b.Path));if !ok{send(w,400,map[string]any{"error":msg});return};a.mu.Lock();a.state.Settings.DropboxPath=strings.TrimSpace(b.Path);a.save();a.mu.Unlock();send(w,200,map[string]any{"ok":true,"path":b.Path});return}
 if p=="/api/dropbox/browse"&&r.Method=="POST"{script:=`Add-Type -AssemblyName System.Windows.Forms; $f=New-Object System.Windows.Forms.FolderBrowserDialog; $f.Description='Escolha a pasta principal da Dropbox'; if($f.ShowDialog() -eq 'OK'){[Console]::OutputEncoding=[Text.UTF8Encoding]::UTF8; Write-Output $f.SelectedPath}`;out,e:=exec.Command("powershell.exe","-NoProfile","-STA","-Command",script).Output();if e!=nil||strings.TrimSpace(string(out))==""{send(w,400,map[string]any{"error":"Nenhuma pasta selecionada."});return};pp:=strings.TrimSpace(string(out));ok,msg:=writable(pp);if !ok{send(w,400,map[string]any{"error":msg});return};a.mu.Lock();a.state.Settings.DropboxPath=pp;a.save();a.mu.Unlock();send(w,200,map[string]any{"ok":true,"path":pp});return}
 if p=="/api/upload"&&r.Method=="PUT"{name:=filepath.Base(r.URL.Query().Get("name"));if name=="."||name==""{name="ficheiro"};a.mu.Lock();db:=a.state.Settings.DropboxPath;a.mu.Unlock();root:=filepath.Join(a.root,"inbox","IB1");if db!=""{root=filepath.Join(db,"DirecaoFiscalizacaoObra","IB1","00_INBOX_IA")};_ = os.MkdirAll(root,0755);dest:=filepath.Join(root,fmt.Sprintf("%d_%s",time.Now().UnixMilli(),name));f,e:=os.Create(dest);if e!=nil{send(w,500,map[string]any{"error":e.Error()});return};n,e:=io.Copy(f,io.LimitReader(r.Body,200<<20));f.Close();if e!=nil{send(w,500,map[string]any{"error":e.Error()});return};d:=Document{ID:fmt.Sprintf("DOC-%d",time.Now().UnixNano()),ProjectID:"IB1",Name:name,Path:dest,Size:n,CreatedAt:time.Now().Format(time.RFC3339),Status:"Recebido"};a.mu.Lock();a.state.Documents=append([]Document{d},a.state.Documents...);a.save();a.mu.Unlock();send(w,200,map[string]any{"ok":true});return}
 send(w,404,map[string]any{"error":"Endpoint inexistente"}) }
func(a *App) handler(w http.ResponseWriter,r *http.Request){if strings.HasPrefix(r.URL.Path,"/api/"){a.api(w,r);return};w.Header().Set("Content-Type","text/html; charset=utf-8");io.WriteString(w,indexHTML)}
func openBrowser(u string){_ = exec.Command("rundll32","url.dll,FileProtocolHandler",u).Start()}
func main(){if runtime.GOOS!="windows"{};a:=newApp();ln,e:=net.Listen("tcp","127.0.0.1:0");if e!=nil{return};a.ln=ln;u:="http://127.0.0.1:"+fmt.Sprint(ln.Addr().(*net.TCPAddr).Port);go http.Serve(ln,http.HandlerFunc(a.handler));time.Sleep(300*time.Millisecond);openBrowser(u);select{}}

const indexHTML = `<!doctype html><html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Direção e Fiscalização de Obra</title><style>body{margin:0;font-family:Segoe UI,Arial;background:#f4f7f8;color:#17212b}.wrap{max-width:1100px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center}.card{background:white;border:1px solid #dce5e8;border-radius:16px;padding:18px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric b{font-size:26px}.two{display:grid;grid-template-columns:1.4fr 1fr;gap:14px}.btn{padding:11px 14px;border-radius:10px;border:1px solid #b9c8cd;background:white;cursor:pointer}.primary{background:#0d8a84;color:white;border-color:#0d8a84}.drop{border:2px dashed #9fb4bb;border-radius:14px;padding:26px;text-align:center}.good{color:#137333}.bad{color:#c52b2b}textarea,input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #cad5da;border-radius:10px;font-size:16px}textarea{min-height:110px}.row{display:flex;gap:8px;flex-wrap:wrap}.answer{white-space:pre-wrap;background:#f6fafb;border-radius:10px;padding:12px;margin-top:10px}@media(max-width:800px){.grid,.two{grid-template-columns:1fr 1fr}}@media(max-width:520px){.grid,.two{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><h1>Direção e Fiscalização de Obra</h1><div>IB1 — Espinho · obra-piloto</div></div><button class="btn" id="config">Configurar</button></div><div class="grid"><div class="card metric">Prazo<br><b>—</b></div><div class="card metric">Execução física<br><b>—</b></div><div class="card metric">Execução financeira<br><b>—</b></div><div class="card metric">Riscos<br><b>0</b></div></div><div class="two"><div class="card"><h2>Assistente IA</h2><div class="row"><button class="btn quick">Como está a obra?</button><button class="btn quick">Riscos 7 dias</button><button class="btn quick">O que falta validar?</button></div><textarea id="prompt" placeholder="Pergunte sobre a obra..."></textarea><button class="btn primary" id="ask">Analisar</button><div id="answer" class="answer" style="display:none"></div></div><div class="card"><h2>Ligações</h2><p>OpenRouter: <b id="or">Por configurar</b></p><p>Dropbox: <b id="db">Por configurar</b></p><input id="key" type="password" placeholder="Chave OpenRouter"><div class="row"><button class="btn" id="savekey">Guardar chave</button><button class="btn" id="testkey">Testar</button></div><br><input id="path" placeholder="C:\Users\Nome\Dropbox"><div class="row"><button class="btn" id="savepath">Guardar caminho</button><button class="btn" id="browse">Escolher pasta</button><button class="btn" id="detect">Detetar</button></div><p id="msg"></p></div></div><div class="card"><h2>Arquivo Vivo</h2><div class="drop" id="drop"><b>Largue aqui documentos ou fotografias</b><br><br><input id="files" type="file" multiple><p id="up"></p></div><div id="docs"></div></div></div><script>const $=s=>document.querySelector(s);async function api(u,o={}){const r=await fetch(u,o);let j={};try{j=await r.json()}catch{}if(!r.ok)throw Error(j.error||('HTTP '+r.status));return j}async function refresh(){try{const s=await api('/api/state');$('#or').textContent=s.connections.openrouter?'Ligado':'Por configurar';$('#or').className=s.connections.openrouter?'good':'bad';$('#db').textContent=s.connections.dropbox?'Ligada':'Por configurar';$('#db').className=s.connections.dropbox?'good':'bad';$('#path').value=s.settings.dropboxPath||'';$('#docs').innerHTML=(s.documents||[]).slice(0,20).map(d=>'<p><b>'+d.Name+'</b> · '+Math.round(d.Size/1024)+' KB</p>').join('')}catch(e){$('#msg').textContent=e.message}}$('#savekey').onclick=async()=>{try{await api('/api/settings/openrouter',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:$('#key').value})});$('#msg').textContent='Chave guardada.';refresh()}catch(e){$('#msg').textContent=e.message}};$('#testkey').onclick=async()=>{try{$('#msg').textContent='A testar...';await api('/api/openrouter/test',{method:'POST'});$('#msg').textContent='OpenRouter OK.'}catch(e){$('#msg').textContent=e.message}};$('#savepath').onclick=async()=>{try{const j=await api('/api/dropbox/set',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:$('#path').value})});$('#msg').textContent='Dropbox: '+j.path;refresh()}catch(e){$('#msg').textContent=e.message}};$('#browse').onclick=async()=>{try{const j=await api('/api/dropbox/browse',{method:'POST'});$('#path').value=j.path;$('#msg').textContent='Dropbox: '+j.path;refresh()}catch(e){$('#msg').textContent=e.message}};$('#detect').onclick=async()=>{try{const j=await api('/api/dropbox/detect',{method:'POST'});$('#path').value=j.path;$('#msg').textContent='Dropbox: '+j.path;refresh()}catch(e){$('#msg').textContent=e.message}};async function ask(){const p=$('#prompt').value.trim();if(!p)return;$('#answer').style.display='block';$('#answer').textContent='A analisar...';try{const j=await api('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:p})});$('#answer').textContent=j.text}catch(e){$('#answer').textContent='Erro: '+e.message}}$('#ask').onclick=ask;document.querySelectorAll('.quick').forEach(b=>b.onclick=()=>{$('#prompt').value=b.textContent;ask()});async function upload(fs){for(const f of fs){$('#up').textContent='A enviar '+f.name;await api('/api/upload?name='+encodeURIComponent(f.name),{method:'PUT',body:f})}$('#up').textContent=fs.length+' ficheiro(s) recebido(s).';refresh()}$('#files').onchange=e=>upload([...e.target.files]);['dragover','drop'].forEach(ev=>$('#drop').addEventListener(ev,e=>{e.preventDefault();if(ev==='drop')upload([...e.dataTransfer.files])}));refresh();</script></body></html>`
